INSERT INTO titles (id, "order", name, freq, parentId, nodeType) VALUES (167, 4, 'ما يقول إذا استيقظ في الليل، وخرج من بيته', 'd', 122, 'content');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (157, 18, 1, 'باسمِكَ اللهمَّ أَحيا وأموتُ', 1, 'ما يقول إذا أراد النوم. (ص130)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (158, 18, 2, '(يجمع كَفَّيْهِ، ثم يَنْفُثُ فيهما، ثم يقرأُ فيهما: ﴿ قُلۡ هُوَ ٱللَّهُ أَحَدٌ ﴾، والمعوِّذتين، ثم يمسح بهما ما استطاع من جسده، يبدأ بهما على رأسِه ووجهِه، وما أقبلَ مِن جَسَدِهِ)، يفعلُ ذلك كُلَّه ثلاثَ مرَّاتٍ.', 3, 'ما يقول إذا أراد النوم. [انظر: «الصحيحة» (٣١٠٤)]. (ص130)', '', '', 'يجمع كفيه ثم ينفث فيهما ثم يقرأ فيهما ﴿ قلۡ هو ٱلله أحد ﴾ والمعوذتين ثم يمسح بهما ما استطاع من جسده يبدأ بهما على رأسه ووجهه وما أقبل من جسده يفعل ذلك كله ثلاث مرات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1528, 18, 3, 'يضع يدَه اليمنى تحت خَدِّه، ثم يقول:', 0, 'ما يقول إذا أراد النوم. (ص130)', '', '', 'يضع يده اليمنى تحت خده ثم يقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (159, 18, 4, 'اللهمَّ قِنِي عذابَكَ يومَ تَبعثُ عبادَكَ', 3, 'ما يقول إذا أراد النوم. (ص130)', '', '', 'اللهم قني عذابك يوم تبعث عبادك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (160, 18, 5, 'باسمِكَ ربِّي وضعتُ جَنْبي، وبكَ أرفعُه، إن أمسكتَ نفسي فارحمْها، وإن أرسلتَها فاحفظْها بما تحفظُ به عبادَكَ الصالحين', 1, 'ما يقول إذا أراد النوم. (ص131)', '', '', 'باسمك ربي وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (161, 18, 6, 'الحمدُ للهِ الذي أطعمَنا، وسقانا، وكفانا، وآوانا، فكَمْ مِمَّن لا كافيَ له ولا مُؤْوِي', 1, 'ما يقول إذا أراد النوم. (ص131)', '', '', 'الحمد لله الذي أطعمنا وسقانا وكفانا وآوانا فكم ممن لا كافي له ولا مؤوي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (162, 18, 7, 'ويقرأ آيةَ الكُرْسِيِّ:
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (163, 18, 8, 'لا إلهَ إلا اللهُ وحدَه، لا شريكَ له، له المُلْكُ، وله الحمدُ، وهو على كلِّ شيءٍ قديرٌ، ولا حولَ ولا قوةَ إلا باللهِ، سبحانَ اللهِ، والحمدُ للهِ، ولا إلهَ إلا اللهُ، واللهُ أكبرُ', 1, 'ما يقول إذا أراد النوم. (ص131)', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير ولا حول ولا قوة إلا بالله سبحان الله والحمد لله ولا إله إلا الله والله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (164, 18, 9, 'اللهمَّ أنتَ خلقتَ نفسي، وأنتَ توفاها، لكَ مماتُها ومحياها، إن أحييتَها فاحفظْها، وإن أمتَّها فاغفرْ لها، اللهمَّ إني أسألُكَ العافية', 1, 'ما يقول إذا أراد النوم. (ص131)', '', '', 'اللهم أنت خلقت نفسي وأنت توفاها لك مماتها ومحياها إن أحييتها فاحفظها وإن أمتها فاغفر لها اللهم إني أسألك العافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (165, 18, 10, 'أعوذُ بكلماتِ اللهِ التامَّاتِ من شرِّ ما خَلَقَ', 1, 'ما يقول إذا أراد النوم. (ص131)', '', '', 'أعوذ بكلمات الله التامات من شر ما خلق', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (166, 18, 11, 'اللهمَّ فاطرَ السماواتِ والأرضِ، عالمَ الغيبِ والشهادةِ، لا إلهَ إلا أنتَ، ربَّ كلِّ شيءٍ ومليكَهُ، أعوذُ بكَ من شرِّ نفسي، ومن شرِّ الشيطانِ وشِركِهِ، وأن أقترفَ على نفسي سوءًا، أو أجرَّه إلى مسلمٍ', 1, 'ما يقول إذا أراد النوم. (ص132)', '', '', 'اللهم فاطر السماوات والأرض عالم الغيب والشهادة لا إله إلا أنت رب كل شيء ومليكه أعوذ بك من شر نفسي ومن شر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (167, 18, 12, 'اللهمَّ ربَّ السماواتِ، وربَّ الأرضِ، وربَّ العرشِ العظيمِ، ربَّنا وربَّ كلِّ شيءٍ، فالِقَ الحَبِّ والنَّوى، مُنزِلَ التوراةِ والإنجيلِ والفُرْقانِ، أعوذُ بكَ من شرِّ كلِّ ذي شرٍّ أنتَ آخِذٌ بناصيتِه، أنتَ الأولُ فليس قبلَكَ شيءٌ، وأنتَ الآخِرُ فليس بعدَكَ شيءٌ، وأنتَ الظاهرُ فليس فوقَكَ شيءٌ، وأنتَ الباطنُ فليس دونَكَ شيءٌ، اقضِ عنَّا الدَّينَ، وأغنِنا من الفقرِ', 1, 'ما يقول إذا أراد النوم. (ص132)', '', '', 'اللهم رب السماوات ورب الأرض ورب العرش العظيم ربنا ورب كل شيء فالق الحب والنوى منزل التوراة والإنجيل والفرقان أعوذ بك من شر كل ذي شر أنت آخذ بناصيته أنت الأول فليس قبلك شيء وأنت الآخر فليس بعدك شيء وأنت الظاهر فليس فوقك شيء وأنت الباطن فليس دونك شيء اقض عنا الدين وأغننا من الفقر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (168, 18, 13, 'اللهمَّ إني أعوذُ بوجهِكَ الكريمِ وكلِماتِكَ التامَّةِ من شرِّ ما أنتَ آخِذٌ بناصيتِه، اللهمَّ أنتَ تَكشِفُ المَغرَمَ والمأثَمَ، اللهمَّ لا يُهزَمُ جُندُكَ، ولا يُخلَفُ وعدُكَ، ولا ينفعُ ذا الجَدِّ منكَ الجَدُّ، سبحانَكَ اللهمَّ وبحمدِكَ', 1, 'ما يقول إذا أراد النوم. (ص132–133)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (169, 18, 14, 'باسمِ اللهِ وضعتُ جَنْبي، اللهمَّ اغفرْ لي ذَنبي، وأَخسِئْ شيطاني، وفُكَّ رِهاني، وثَقِّلْ ميزاني، واجعلْني في النَّدِيِّ الأعلى', 1, 'ما يقول إذا أراد النوم. (ص133)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (170, 18, 15, 'الحمدُ للهِ الذي كفاني وآواني، وأطعَمَني وأسقاني، والذي مَنَّ عليَّ فأفضلَ، والذي أعطاني فأجزلَ، الحمدُ للهِ على كلِّ حالٍ، اللهمَّ ربَّ كلِّ شيءٍ ومليكَهُ، وإلهَ كلِّ شيءٍ، أعوذُ بكَ من النار', 1, 'ما يقول إذا أراد النوم. (ص133)', '', '', 'الحمد لله الذي كفاني وآواني وأطعمني وأسقاني والذي من علي فأفضل والذي أعطاني فأجزل الحمد لله على كل حال اللهم رب كل شيء ومليكه وإله كل شيء أعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1529, 18, 16, 'ويقول:', 0, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'ويقول', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (171, 18, 17, 'اللهُ أكبرُ', 34, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (172, 18, 18, 'سبحانَ اللهِ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (173, 18, 19, 'الحمدُ للهِ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (963, 18, 20, 'أو: اللهُ أكبرُ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'أو الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (964, 18, 21, 'سبحانَ اللهِ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (965, 18, 22, 'الحمدُ للهِ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (966, 18, 23, 'أو: اللهُ أكبرُ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'أو الله أكبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (967, 18, 24, 'سبحانَ اللهِ', 34, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'سبحان الله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (968, 18, 25, 'الحمدُ للهِ', 33, 'ما يقول إذا أراد النوم. (ص134)', '', '', 'الحمد لله', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (174, 18, 26, 'اللهمَّ إني أسألُكَ رؤيا صالحةً، صادقةً غيرَ كاذبةٍ، نافعةً غيرَ ضَارَّةٍ', 1, 'ما يقول إذا أراد النوم. [موقوفٌ على عائشة رضي الله عنها]. (ص134)', '', '', 'اللهم إني أسألك رؤيا صالحة صادقة غير كاذبة نافعة غير ضارة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (175, 18, 27, 'يقرأ سورة:
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1530, 18, 28, 'وليكن آخر ما يقول:', 0, 'ما يقول إذا أراد النوم. (ص135)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (176, 18, 29, 'اللهمَّ أسلمتُ نفسي إليكَ، ووجَّهتُ وجهي إليكَ، وفوَّضتُ أمري إليكَ، وألجأتُ ظهري إليكَ، رغبةً ورهبةً إليكَ، لا مَلجأَ ولا مَنجى منكَ إلا إليكَ، اللهمَّ آمنتُ بكتابِكَ الذي أنزلتَ، وبِنبيِّكَ الذي أرسلتَ', 1, 'ما يقول إذا أراد النوم. (ص135)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1531, 30, 1, 'إذا رأى في منامه ما يحب:', 0, 'من آداب الرؤيا. (ص135)', '', '', 'إذا رأى في منامه ما يحب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (969, 30, 2, 'يحمدُ اللهَ عليه، ولا يُحَدِّثْ به إلَّا مَنْ يُحِبُّ.', 0, 'من آداب الرؤيا. (ص135)', '', '', 'يحمد الله عليه ولا يحدث به إلا من يحب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1532, 30, 3, 'وإذا رأى ما يكره:', 0, 'من آداب الرؤيا. (ص135)', '', '', 'وإذا رأى ما يكره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (970, 30, 4, 'فَلْيَسْتَعِذْ باللهِ من شَرِّه.', 1, 'من آداب الرؤيا. (ص135)', '', '', 'فليستعذ بالله من شره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (971, 30, 5, 'وَيَنفُثُ عن يَسارِه.', 3, 'من آداب الرؤيا. (ص136)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (972, 30, 6, 'ويتعوَّذ باللهِ مِنَ الشيطانِ الرَّجيم.', 3, 'من آداب الرؤيا. (ص136)', '', '', 'ويتعوذ بالله من الشيطان الرجيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (973, 30, 7, 'ويتحوَّل عن جَنبِهِ الذي كان عليه.', 0, 'من آداب الرؤيا. (ص136)', '', '', 'ويتحول عن جنبه الذي كان عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1533, 30, 8, 'ولا يُحَدِّث بها أحدًا.', 0, 'من آداب الرؤيا. (ص136)', '', '', 'ولا يحدث بها أحدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1534, 30, 9, 'ولْيَقُمْ فَلْيُصَلِّ إن أمكنه؛ فإنَّ ذلكَ أتمُّ وأكمَلُ.', 0, 'من آداب الرؤيا. (ص136)', '', '', 'وليقم فليصل إن أمكنه فإن ذلك أتم وأكمل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1535, 30, 10, 'وإن كان يُفَزَّعُ في منامه؛ قال إذا أوى إلى فراشه:', 0, 'من آداب الرؤيا. (ص136)', '', '', 'وإن كان يفزع في منامه قال إذا أوى إلى فراشه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (212, 30, 11, 'أعوذُ بكلماتِ اللهِ التامَّةِ، من غضبِهِ وعِقابِهِ، ومن شرِّ عبادِهِ، ومن هَمَزاتِ الشياطين، وأن يَحضُرونِ', 1, 'من آداب الرؤيا. [«الصحيحة» (٢٦٤)]. (ص136)', '', '', 'أعوذ بكلمات الله التامة من غضبه وعقابه ومن شر عباده ومن همزات الشياطين وأن يحضرون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (213, 30, 12, 'أعوذُ بكلماتِ اللهِ التامَّاتِ التي لا يُجاوزُهُنَّ بَرٌّ ولا فاجرٌ، من شرِّ ما ينزلُ من السماء، وما يَعْرُجُ فيها، ومن شرِّ فِتَنِ الليلِ والنهارِ، ومن كلِّ طارقٍ، إلا طارقًا يطرقُ بخيرٍ، يا رحمن', 1, 'من آداب الرؤيا. [«الصحيحة» (٢٧٣٨)]. (ص136)', '', '', 'أعوذ بكلمات الله التامات التي لا يجاوزهن بر ولا فاجر من شر ما ينزل من السماء وما يعرج فيها ومن شر فتن الليل والنهار ومن كل طارق إلا طارقا يطرق بخير يا رحمن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (214, 31, 1, 'قال رسول الله ﷺ: «من تَعارَّ من الليلِ، فقال حين يستيقظُ: (لا إله إلا اللهُ وحدَه، لا شريكَ له، له المُلْكُ، وله الحمدُ، يُحيِي وَيُمِيتُ، بيدِه الخيرُ، وَهُوَ على كلِّ شيءٍ قديرٌ، سبحانَ اللهِ، والحمدُ للهِ، ولا إله إلا اللهُ، واللهُ أكبرُ، ولا حولَ ولا قوةَ إلا باللهِ)، ثُمَّ قال: (اللهُمَّ اغفِرْ لي)، أو دعا، استُجيبَ له، فإن قام فتوضَّأَ، ثُمَّ صَلَّى؛ قُبِلت صلاتُه».', 0, 'ما يقول إذا استيقظ في الليل. (ص137)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1536, 31, 2, 'وإذا تَضَوَّرَ من الليلِ، قال:', 0, 'ما يقول إذا استيقظ في الليل. (ص138)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (215, 31, 3, 'لا إلهَ إلا اللهُ الواحدُ القهّارُ، ربُّ السماواتِ والأرضِ وما بينهما العزيزُ الغفّارُ', 1, 'ما يقول إذا استيقظ في الليل. (ص138)', '', '', 'لا إله إلا الله الواحد القهار رب السماوات والأرض وما بينهما العزيز الغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1537, 31, 4, 'وقال ﷺ: «مَن آوَى إلى فِراشِهِ طاهِرًا، لَم ينقَلِب ساعةً منَ اللَّيلِ، يسألُ اللهَ شيئًا مِن خيرِ الدُّنيا والآخرةِ؛ إلَّا أعطاهُ اللهُ إيَّاهُ».', 0, 'ما يقول إذا استيقظ في الليل. (ص138)', '', '', 'وقال «من آوى إلى فراشه طاهرا لم ينقلب ساعة من الليل يسأل الله شيئا من خير الدنيا والآخرة إلا أعطاه الله إياه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1538, 31, 5, 'وإذا قامَ عَنْ فِراشِه، ثُمَّ عادَ إليه، فَلْيَنْفُضْهُ بِصَنِفَةِ إزاره ثلاثَ مرَّاتٍ، فإنَّه لا يدري ما خَلَفَهُ عليه، فإذا اضطَجَعَ فَلْيَقُل:', 0, 'ما يقول إذا استيقظ في الليل. (ص138)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (974, 31, 6, 'باسمِكَ اللهمَّ وضعتُ جَنْبي، وبكَ أرفعُه، إن أمسكتَ نفسي فارحمْها، وإن رددتَها فاحفظْها بما تحفظُ به عبادَكَ الصالحين', 1, 'ما يقول إذا استيقظ في الليل. (ص138)', '', '', 'باسمك اللهم وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها وإن رددتها فاحفظها بما تحفظ به عبادك الصالحين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (216, 167, 1, 'ينظُرُ إلى السماءِ ويقرأُ عشرَ الآياتِ خواتيم سورةِ آل عمران:
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1539, 167, 2, 'وقال ﷺ: «أقربُ ما يكونُ الرَّبُّ من العبدِ، في جَوفِ الليلِ الآخِرِ، فإنِ استَطَعتَ أن تكونَ ممَّن يَذْكُرُ اللهَ في تِلكَ السَّاعةِ؛ فَكُن».', 0, 'ما يقول إذا استيقظ في الليل، وخرج من بيته. (ص139)', '', '', 'وقال «أقرب ما يكون الرب من العبد في جوف الليل الآخر فإن استطعت أن تكون ممن يذكر الله في تلك الساعة فكن»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1540, 167, 3, 'وقال ﷺ: «يَنزِلُ رَبُّنا تَبَارَكَ وَتَعَالَى كُلَّ ليلةٍ إلى سماءِ الدُّنيا، حينَ يبقى ثُلُثُ اللَّيلِ الآخِرِ، فيقولُ: مَن يدعوني فأستجيبَ له؟ مَن يسألُني فأُعطِيَه؟ مَن يستغفِرُني فأغفِرَ له؟».', 0, 'ما يقول إذا استيقظ في الليل، وخرج من بيته. (ص139)', '', '', 'وقال «ينزل ربنا تبارك وتعالى كل ليلة إلى سماء الدنيا حين يبقى ثلث الليل الآخر فيقول من يدعوني فأستجيب له من يسألني فأعطيه من يستغفرني فأغفر له »', '', '');
